/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

export interface FileUploadFile {
  file: File;
  id: string;
  error?: string;
}

export type FileUploadProps = Omit<
  ComponentProps<"div">,
  "onChange" | "children"
> &
  VariantProps<typeof fileUploadVariants> & {
    /** Accepted MIME types (e.g. "image/*,.pdf") */
    accept?: string;
    /** Allow selecting multiple files */
    multiple?: boolean;
    /** Maximum file size in bytes */
    maxSize?: number;
    /** Maximum number of files */
    maxFiles?: number;
    /** Currently selected files (controlled) */
    files?: FileUploadFile[];
    /** Callback when files change */
    onFilesChange?: (files: FileUploadFile[]) => void;
    /** Custom placeholder title */
    title?: string;
    /** Custom placeholder description */
    description?: string;
    /** Whether the upload zone is disabled */
    disabled?: boolean;
  };

/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */

function generateId() {
  return Math.random().toString(36).slice(2, 10);
}

function formatFileSize(bytes: number): string {
  if (bytes === 0) return "0 B";
  const units = ["B", "KB", "MB", "GB"];
  const i = Math.floor(Math.log(bytes) / Math.log(1024));
  return `${(bytes / 1024 ** i).toFixed(i === 0 ? 0 : 1)} ${units[i]}`;
}

/* ------------------------------------------------------------------ */
/*  Component                                                          */
/* ------------------------------------------------------------------ */

export function FileUpload({
  className,
  variant = "default",
  size = "md",
  accept,
  multiple = false,
  maxSize,
  maxFiles,
  files: controlledFiles,
  onFilesChange,
  title: titleText,
  description: descriptionText,
  disabled = false,
  ...props
}: FileUploadProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [dragging, setDragging] = useState(false);
  const [internalFiles, setInternalFiles] = useState<FileUploadFile[]>([]);

  const isControlled = controlledFiles !== undefined;
  const files = isControlled ? controlledFiles : internalFiles;

  const updateFiles = useCallback(
    (next: FileUploadFile[]) => {
      if (!isControlled) {
        setInternalFiles(next);
      }
      onFilesChange?.(next);
    },
    [isControlled, onFilesChange],
  );

  const validateFile = useCallback(
    (file: File): string | undefined => {
      if (maxSize && file.size > maxSize) {
        return `Arquivo excede ${formatFileSize(maxSize)}`;
      }
      return undefined;
    },
    [maxSize],
  );

  const addFiles = useCallback(
    (incoming: File[]) => {
      if (disabled) return;

      const newEntries: FileUploadFile[] = incoming.map((file) => ({
        file,
        id: generateId(),
        error: validateFile(file),
      }));

      let nextFiles: FileUploadFile[];
      if (multiple) {
        nextFiles = [...files, ...newEntries];
        if (maxFiles && nextFiles.length > maxFiles) {
          nextFiles = nextFiles.slice(0, maxFiles);
        }
      } else {
        nextFiles = newEntries.slice(0, 1);
      }

      updateFiles(nextFiles);
    },
    [disabled, files, multiple, maxFiles, validateFile, updateFiles],
  );

  const removeFile = useCallback(
    (id: string) => {
      updateFiles(files.filter((f) => f.id !== id));
    },
    [files, updateFiles],
  );

  /* — Drag events — */
  const handleDragOver = useCallback(
    (e: DragEvent<HTMLDivElement>) => {
      e.preventDefault();
      e.stopPropagation();
      if (!disabled) setDragging(true);
    },
    [disabled],
  );

  const handleDragLeave = useCallback((e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setDragging(false);
  }, []);

  const handleDrop = useCallback(
    (e: DragEvent<HTMLDivElement>) => {
      e.preventDefault();
      e.stopPropagation();
      setDragging(false);
      if (e.dataTransfer?.files) {
        addFiles(Array.from(e.dataTransfer.files));
      }
    },
    [addFiles],
  );

  const handleChange = useCallback(
    (e: ChangeEvent<HTMLInputElement>) => {
      if (e.target.files) {
        addFiles(Array.from(e.target.files));
      }
      e.target.value = "";
    },
    [addFiles],
  );

  const handleClick = useCallback(() => {
    if (!disabled) inputRef.current?.click();
  }, [disabled]);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLDivElement>) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        handleClick();
      }
    },
    [handleClick],
  );

  /* — Styles — */
  const styles = fileUploadVariants({
    variant,
    size,
    isDragging: dragging,
    disabled,
  });

  const defaultTitle = dragging
    ? "Solte os arquivos aqui"
    : "Arraste e solte seus arquivos";

  const defaultDescription = multiple
    ? "ou clique para selecionar vários arquivos"
    : "ou clique para selecionar um arquivo";

  return (
    <div data-slot="file-upload" className="w-full">
      {/* — Drop zone — */}
      {/* biome-ignore lint/a11y/useSemanticElements: Esta div atua como um dropzone complexo */}
      <div
        role="button"
        tabIndex={disabled ? -1 : 0}
        aria-label="Área de upload de arquivos"
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        onClick={handleClick}
        onKeyDown={handleKeyDown}
        className={twMerge(styles.root(), className)}
        {...props}
      >
        <span className={styles.icon()}>
          <Upload aria-hidden="true" />
        </span>

        <div className="flex flex-col gap-1">
          <span className={styles.title()}>{titleText ?? defaultTitle}</span>
          <span className={styles.description()}>
            {descriptionText ?? defaultDescription}
          </span>
        </div>

        {accept && (
          <span className="text-[10px] text-muted-foreground/60">{accept}</span>
        )}
      </div>

      {/* — Hidden input — */}
      <input
        ref={inputRef}
        type="file"
        className="sr-only"
        accept={accept}
        multiple={multiple}
        onChange={handleChange}
        tabIndex={-1}
        aria-hidden="true"
      />

      {/* — File list — */}
      {files.length > 0 && (
        <ul className={styles.fileList()} data-slot="file-upload-list">
          {files.map((entry) => (
            <li key={entry.id} className={styles.fileItem()}>
              <FileText
                className="size-4 shrink-0 text-muted-foreground"
                aria-hidden="true"
              />

              <span className={styles.fileName()}>{entry.file.name}</span>

              <span className={styles.fileSize()}>
                {formatFileSize(entry.file.size)}
              </span>

              {entry.error && (
                <span className={styles.errorText()}>
                  <AlertCircle className="size-3.5" aria-hidden="true" />
                  {entry.error}
                </span>
              )}

              <button
                type="button"
                aria-label={`Remover ${entry.file.name}`}
                className={styles.removeButton()}
                onClick={(e) => {
                  e.stopPropagation();
                  removeFile(entry.id);
                }}
              >
                <X className="size-3.5" aria-hidden="true" />
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

'use client'

import {
  AnimatePresence,
  motion,
  type PanInfo,
  type Variants
} from 'framer-motion'
import { X } from 'lucide-react'
import {
  type ComponentProps,
  createContext,
  type ReactNode,
  useCallback,
  useContext,
  useMemo,
  useRef,
  useState
} from 'react'
import { twMerge } from 'tailwind-merge'
import { tv, type VariantProps } from 'tailwind-variants'

export const notificationStackVariants = tv({
  base: ['relative flex flex-col items-center'],
  variants: {
    size: {
      sm: 'w-[300px]',
      md: 'w-[360px]',
      lg: 'w-[420px]'
    }
  },
  defaultVariants: {
    size: 'md'
  }
})

export const notificationCardVariants = tv({
  base: [
    'w-full overflow-hidden rounded-[16px] border border-border',
    'bg-secondary text-foreground shadow-lg'
  ]
})

export type NotificationData = {
  id: string
  app?: string
  title: string
  description?: string
  avatar?: ReactNode
  timestamp?: string
  action?: {
    label: string
    onClick: () => void
  }
}

type NotificationContextValue = {
  notifications: NotificationData[]
  add: (notification: Omit<NotificationData, 'id'>) => string
  dismiss: (id: string) => void
  dismissAll: () => void
}

const NotificationContext = createContext<NotificationContextValue | null>(null)

export function useNotificationStack() {
  const ctx = useContext(NotificationContext)
  if (!ctx) {
    throw new Error(
      'useNotificationStack must be used within a NotificationStackProvider'
    )
  }
  return ctx
}

export type NotificationStackProviderProps = {
  children: ReactNode
}

export function NotificationStackProvider({
  children
}: NotificationStackProviderProps) {
  const [notifications, setNotifications] = useState<NotificationData[]>([])
  const counterRef = useRef(0)

  const add = useCallback((notification: Omit<NotificationData, 'id'>) => {
    counterRef.current += 1
    const id = `notification-${counterRef.current}-${Date.now()}`
    const newNotification: NotificationData = { ...notification, id }
    setNotifications(prev => [...prev, newNotification])
    return id
  }, [])

  const dismiss = useCallback((id: string) => {
    setNotifications(prev => prev.filter(n => n.id !== id))
  }, [])

  const dismissAll = useCallback(() => {
    setNotifications([])
  }, [])

  const value = useMemo(
    () => ({ notifications, add, dismiss, dismissAll }),
    [notifications, add, dismiss, dismissAll]
  )

  return (
    <NotificationContext.Provider value={value}>
      {children}
    </NotificationContext.Provider>
  )
}

const cardVariants: Variants = {
  initial: { opacity: 0, y: -30, scale: 0.96 },
  animate: {
    opacity: 1,
    y: 0,
    scale: 1,
    transition: {
      type: 'spring',
      stiffness: 380,
      damping: 26,
      mass: 0.8
    }
  },
  exit: {
    opacity: 0,
    y: -50,
    scale: 0.93,
    transition: {
      duration: 0.25,
      ease: [0.36, 0, 0.66, -0.56]
    }
  }
}

const stackLayerVariants: Variants = {
  initial: { opacity: 0, scale: 0.9, y: 0 },
  animate: (i: number) => ({
    opacity: 1,
    scaleX: 1 - i * 0.04,
    scaleY: 1,
    y: i * 5, // reduzido de 8 → 5
    transition: {
      type: 'spring',
      stiffness: 300,
      damping: 24,
      delay: i * 0.05
    }
  }),
  exit: {
    opacity: 0,
    scale: 0.9,
    transition: { duration: 0.2 }
  }
}

export type NotificationStackProps = ComponentProps<'div'> &
  VariantProps<typeof notificationStackVariants> & {
    notifications: NotificationData[]
    onDismiss?: (id: string) => void
    maxStackLayers?: number
  }

export function NotificationStack({
  className,
  size,
  notifications,
  onDismiss,
  maxStackLayers = 3,
  ...props
}: NotificationStackProps) {
  const topNotification = notifications[notifications.length - 1]
  const stackCount = Math.min(notifications.length - 1, maxStackLayers)
  const remainingCount = notifications.length - 1

  function handleDragEnd(_: unknown, info: PanInfo) {
    if (!topNotification) return
    if (Math.abs(info.offset.y) > 80 || Math.abs(info.offset.x) > 120) {
      onDismiss?.(topNotification.id)
    }
  }

  return (
    <div
      data-slot="notification-stack"
      className={twMerge(notificationStackVariants({ size }), className)}
      {...props}
    >
      <div
        className="relative w-full"
        style={{ paddingBottom: stackCount * 5 }} // reduzido de 8 → 5
      >
        <AnimatePresence>
          {Array.from({ length: stackCount }).map((_, i) => {
            const layerIndex = stackCount - i
            return (
              <motion.div
                key={`stack-layer-${layerIndex}`}
                custom={layerIndex}
                variants={stackLayerVariants}
                initial="initial"
                animate="animate"
                exit="exit"
                className="absolute inset-x-0 bottom-0 top-0 z-0 origin-bottom"
                style={{ zIndex: i }}
              >
                <div
                  className={twMerge(
                    notificationCardVariants(),
                    'h-full w-full'
                  )}
                  style={{ opacity: 0.3 + i * 0.2 }}
                />
              </motion.div>
            )
          })}
        </AnimatePresence>

        <AnimatePresence mode="popLayout">
          {topNotification ? (
            <motion.div
              key={topNotification.id}
              variants={cardVariants}
              initial="initial"
              animate="animate"
              exit="exit"
              drag
              dragConstraints={{ left: 0, right: 0, top: 0, bottom: 0 }}
              dragElastic={0.5}
              onDragEnd={handleDragEnd}
              className="relative cursor-grab active:cursor-grabbing"
              style={{ zIndex: stackCount + 1 }}
            >
              <div className={notificationCardVariants()}>
                {/* Header — mais compacto */}
                <div className="flex items-center justify-between px-3 pt-2.5 pb-1.5">
                  {topNotification.app && (
                    <motion.span
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
